  async function start(){const params=new URLSearchParams(location.search);if(params.get('dang-nhap')==='that-bai')error.textContent='Đăng nhập chưa hoàn tất. Kiểm tra cấu hình Google OAuth rồi thử lại.';try{const auth=await request('auth/me');if(!auth.authenticated){loginPanel.hidden=false;profilePanel.hidden=true;if(intro)intro.hidden=false;status.hidden=false;status.textContent='Bạn chưa đăng nhập.';initAccountCaptcha();return}const user=auth.user||{};loginPanel.hidden=true;profilePanel.hidden=false;if(intro){intro.hidden=false;intro.textContent='Đã đăng nhập. Hồ sơ đã lưu của bạn được đồng bộ trên mọi thiết bị.'}status.textContent='';status.hidden=true;$('#account-name').textContent=user.name||'Thành viên';$('#account-email').textContent=user.email||'';$('#account-avatar').textContent=(user.name||'T').trim().charAt(0).toLocaleUpperCase('vi-VN');$('#account-role').textContent=user.role==='admin'?'Quản trị viên':'Thành viên';const legacy=storage.get('mtk-saved',[]);if(Array.isArray(legacy)&&legacy.length){try{await request('saved-pages',{action:'import',slugs:legacy});localStorage.removeItem('mtk-saved');status.textContent='Hồ sơ đã lưu trên thiết bị này được đồng bộ vào tài khoản.';status.hidden=false}catch{status.textContent='Một số hồ sơ cũ chưa đồng bộ được; các hồ sơ mới vẫn lưu bình thường.';status.hidden=false}}const [savedResponse,indexResponse]=await Promise.all([request('saved-pages'),fetch('/saved-pages-index.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Không tải được danh mục hồ sơ.');return r.json()})]);renderSaved(savedResponse.saved||[],indexResponse)}catch(e){loginPanel.hidden=true;profilePanel.hidden=true;status.hidden=false;status.textContent='Không tải được trạng thái tài khoản.';error.textContent=e.message}}
