 const render=items=>{list.replaceChildren();for(let index=0;index<items.length;index++){const item=items[index],row=el('article',undefined,'supporter-entry'),identity=el('div',undefined,'supporter-entry-identity'),seal=el('span',undefined,'supporter-entry-seal'),name=el('strong',item.display_name),dateValue=new Date(item.created_at),date=el('time',Number.isNaN(dateValue.getTime())?'':dateValue.toLocaleDateString('vi-VN',{day:'2-digit',month:'long',year:'numeric'}),'supporter-entry-date');seal.setAttribute('aria-hidden','true');seal.innerHTML='<svg viewBox="0 0 24 24"><path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9L12 3Z"/></svg>';if(!Number.isNaN(dateValue.getTime()))date.dateTime=dateValue.toISOString();identity.append(seal,name);row.append(identity,date);list.append(row)}if(!items.length)list.append(el('p',search.value.trim()?'Không tìm thấy người ghi danh phù hợp.':'Danh sách sẽ được cập nhật sau khi chủ website xác nhận các khoản ghi danh.','empty'))};
